mod bmb_cert {
    spec fn never() -> bool { false }

    #[effects(pure)]
    #[uses(tasks::grown)]
    fn refute(a: &mut [i64]) -> ()
        ensures never(),
    {
        tasks::grow(a)
    }

    #[effects(pure)]
    fn reach() -> () {
        let mut e: [i64; 1] = [0];
        refute(&mut e)
    }
